create table if not exists public.regulated_plant_rules (
  id uuid primary key default gen_random_uuid(),
  taxon_name text not null,
  normalized_taxon_name text not null,
  taxon_rank text not null check (taxon_rank in ('species', 'genus', 'family', 'common_name')),
  match_type text not null check (match_type in ('exact', 'broad')),
  family text,
  common_name text,
  normalized_common_name text,
  source_category text,
  dao_category_code text,
  status text not null check (status in ('needs_permit', 'needs_review', 'illegal')),
  regulation_ref text not null,
  seller_explanation text not null,
  source_document text not null,
  source_url text,
  last_verified_at date not null,
  notes text,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (source_document, normalized_taxon_name, taxon_rank, regulation_ref)
);
comment on table public.regulated_plant_rules is 'GrowMate compliance helper for regulated plant sale/transport review. Not legal advice.';
create index if not exists regulated_plant_rules_normalized_taxon_idx on public.regulated_plant_rules (normalized_taxon_name) where active;
create index if not exists regulated_plant_rules_normalized_common_idx on public.regulated_plant_rules (normalized_common_name) where active and normalized_common_name is not null;
create index if not exists regulated_plant_rules_status_idx on public.regulated_plant_rules (status) where active;
alter table public.regulated_plant_rules enable row level security;
drop policy if exists "authenticated read regulated plant rules" on public.regulated_plant_rules;
create policy "authenticated read regulated plant rules" on public.regulated_plant_rules for select to authenticated using (active = true);
drop trigger if exists regulated_plant_rules_set_updated_at on public.regulated_plant_rules;
create trigger regulated_plant_rules_set_updated_at before update on public.regulated_plant_rules for each row execute function public.set_updated_at();
delete from public.regulated_plant_rules where source_document in ('DAO-2026-20', 'RA 9165', 'CITES Checklist');
insert into public.regulated_plant_rules (taxon_name, normalized_taxon_name, taxon_rank, match_type, family, common_name, normalized_common_name, source_category, dao_category_code, status, regulation_ref, seller_explanation, source_document, source_url, last_verified_at, notes, active)
select taxon_name, normalized_taxon_name, taxon_rank, match_type, nullif(family, ''), nullif(common_name, ''), normalized_common_name, nullif(source_category, ''), nullif(dao_category_code, ''), status, regulation_ref, seller_explanation, source_document, nullif(source_url, ''), last_verified_at::date, nullif(notes, ''), active
from jsonb_to_recordset($json$
